def transform(g):
    h,w=len(g),len(g[0])
    # separator columns: fully uniform, color that fills entire column
    seps={c for c in range(w) if len({g[r][c] for r in range(h)})==1}
    # build runs of non-separator columns
    runs=[]
    for c in range(w):
        if c in seps: continue
        if runs and runs[-1][1]==c: runs[-1][1]=c+1
        else: runs.append([c,c+1])
    # pattern run = run that is not column-uniform
    pat=[r for r in runs if any(len({g[row][c] for row in range(h)})>1 for c in range(r[0],r[1]))]
    if len(pat)!=1: return g
    a,b=pat[0]
    out=[row[:] for row in g]
    for r in range(h):
        p=g[r][a:b]; pw=b-a
        for x,y in runs:
            if (x,y)==(a,b): continue
            for c in range(x,y):
                out[r][c]=p[(c-x)%pw]
    return out
